create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,display_name text,role text not null default 'customer' check(role in('customer','admin')),created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,display_name,role) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'display_name',''),'customer') on conflict(id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,description text,price numeric(12,2) not null default 0 check(price>=0),image_path text,category text not null default 'New Release',active boolean default true,stock integer default 0,created_at timestamptz default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),order_number text unique default('IV-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),customer_id uuid not null references public.profiles(id),total numeric(12,2) not null check(total>=0),status text not null default 'pending' check(status in('pending','in_studio','painted','shipped','cancelled')),payment_status text not null default 'unpaid' check(payment_status in('unpaid','pending','paid','failed','refunded')),payment_reference text,created_at timestamptz default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id),product_name text not null,unit_price numeric(12,2) not null,quantity integer not null check(quantity>0));
create table if not exists public.custom_requests(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.profiles(id),title text not null default 'Custom concept',notes text,style_tags text[] not null default '{}',image_path text,status text not null default 'new' check(status in('new','reviewing','quoted','accepted','declined','completed')),quote_amount numeric(12,2),created_at timestamptz default now());
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.profiles(id),subject text not null default 'Customer support',updated_at timestamptz default now(),created_at timestamptz default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references public.profiles(id),body text not null check(char_length(body) between 1 and 5000),created_at timestamptz default now());
create table if not exists public.partner_notes(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id),body text not null check(char_length(body) between 1 and 5000),created_at timestamptz default now());
create table if not exists public.brand_settings(key text primary key,value text not null,updated_at timestamptz default now(),updated_by uuid references public.profiles(id));
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','products','orders','order_items','custom_requests','conversations','messages','partner_notes','brand_settings'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
create policy "profile own or admin read" on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy "profile own update" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
-- Prevent customers from changing their own role through the Data API.
revoke update on public.profiles from authenticated;
grant update(display_name) on public.profiles to authenticated;
create policy "products public read" on public.products for select using(active or public.is_admin()); create policy "products admin all" on public.products for all using(public.is_admin()) with check(public.is_admin());
create policy "orders own/admin read" on public.orders for select using(customer_id=auth.uid() or public.is_admin()); create policy "orders customer insert" on public.orders for insert with check(customer_id=auth.uid()); create policy "orders admin update" on public.orders for update using(public.is_admin()) with check(public.is_admin());
create policy "items own/admin read" on public.order_items for select using(public.is_admin() or exists(select 1 from public.orders o where o.id=order_id and o.customer_id=auth.uid())); create policy "items own insert" on public.order_items for insert with check(exists(select 1 from public.orders o where o.id=order_id and o.customer_id=auth.uid()));
create policy "requests own/admin read" on public.custom_requests for select using(customer_id=auth.uid() or public.is_admin()); create policy "requests own insert" on public.custom_requests for insert with check(customer_id=auth.uid()); create policy "requests admin update" on public.custom_requests for update using(public.is_admin()) with check(public.is_admin());
create policy "conversations own/admin read" on public.conversations for select using(customer_id=auth.uid() or public.is_admin()); create policy "conversations own insert" on public.conversations for insert with check(customer_id=auth.uid()); create policy "conversations admin update" on public.conversations for update using(public.is_admin()) with check(public.is_admin());
create policy "messages participants read" on public.messages for select using(public.is_admin() or exists(select 1 from public.conversations c where c.id=conversation_id and c.customer_id=auth.uid())); create policy "messages participants send" on public.messages for insert with check(sender_id=auth.uid() and exists(select 1 from public.conversations c where c.id=conversation_id and (c.customer_id=auth.uid() or public.is_admin())));
create policy "partner notes admin only" on public.partner_notes for all using(public.is_admin()) with check(public.is_admin()); create policy "brand settings public read" on public.brand_settings for select using(true); create policy "brand settings admin manage" on public.brand_settings for all using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('custom-references','custom-references',false,8388608,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do update set public=false,file_size_limit=8388608;
create policy "upload own reference" on storage.objects for insert to authenticated with check(bucket_id='custom-references' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "read own or admin reference" on storage.objects for select to authenticated using(bucket_id='custom-references' and ((storage.foldername(name))[1]=auth.uid()::text or public.is_admin()));
create policy "admin delete references" on storage.objects for delete to authenticated using(bucket_id='custom-references' and public.is_admin());
